<script>
(function () {
  const DATA = JSON.parse(document.getElementById('report-data').textContent);
  const root = document.querySelector('.viz-root');
  const css = getComputedStyle(root);
  const cssVar = (name) => css.getPropertyValue(name).trim();

  function compact(n) {
    if (n >= 1e9) return (n / 1e9).toFixed(1).replace(/\.0$/, '') + 'B';
    if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
    return String(n);
  }
  function commas(n) { return n.toLocaleString('en-US'); }

  // ---- KPI tiles ----
  const s = DATA.summary;
  const kpis = [
    { label: 'Total requests', value: compact(s.total_requests) },
    { label: 'Allowed requests', value: compact(s.allowed_requests), cls: 'allowed-ink' },
    { label: 'Blocked requests', value: compact(s.blocked_requests), cls: 'blocked-ink' },
    { label: 'Block rate', value: s.block_rate_pct + '%', cls: 'blocked-ink' },
    { label: 'Unique domains seen', value: compact(s.unique_domains) },
    { label: 'Active identities', value: commas(s.identities) },
  ];
  const kpiRow = document.getElementById('kpi-row');
  kpis.forEach(k => {
    const tile = document.createElement('div');
    tile.className = 'tile';
    tile.innerHTML = `<div class="label">${k.label}</div><div class="value ${k.cls || ''}">${k.value}</div>`;
    kpiRow.appendChild(tile);
  });

  const range = DATA.daily_series;
  document.getElementById('date-range-label').textContent =
    `${range[0].date} → ${range[range.length - 1].date} (${range.length} days)`;

  // ---- Trend line chart (allowed vs blocked) ----
  (function trendChart() {
    const svg = document.getElementById('trend-chart');
    const tooltip = document.getElementById('trend-tooltip');
    const W = 1120, H = 300;
    const padL = 46, padR = 12, padT = 12, padB = 28;
    const plotW = W - padL - padR, plotH = H - padT - padB;
    const n = range.length;
    const maxV = Math.max(...range.map(d => d.allowed));
    const niceMax = Math.ceil(maxV / 1e6) * 1e6;

    const x = (i) => padL + (i / (n - 1)) * plotW;
    const y = (v) => padT + plotH - (v / niceMax) * plotH;

    let svgns = 'http://www.w3.org/2000/svg';
    function el(tag, attrs) {
      const e = document.createElementNS(svgns, tag);
      for (const k in attrs) e.setAttribute(k, attrs[k]);
      return e;
    }

    // gridlines + y ticks
    const steps = 4;
    for (let i = 0; i <= steps; i++) {
      const v = (niceMax / steps) * i;
      const gy = y(v);
      svg.appendChild(el('line', { x1: padL, x2: W - padR, y1: gy, y2: gy, class: 'grid-line' }));
      const t = el('text', { x: padL - 8, y: gy + 4, 'text-anchor': 'end' });
      t.textContent = compact(v);
      svg.appendChild(t);
    }
    // x baseline
    svg.appendChild(el('line', { x1: padL, x2: W - padR, y1: padT + plotH, y2: padT + plotH, class: 'axis-line' }));

    // x ticks: show ~6 dates
    const tickEvery = Math.ceil(n / 6);
    for (let i = 0; i < n; i += tickEvery) {
      const t = el('text', { x: x(i), y: H - 8, 'text-anchor': 'middle' });
      t.textContent = range[i].date.slice(5);
      svg.appendChild(t);
    }

    function pathFor(key) {
      return range.map((d, i) => `${i === 0 ? 'M' : 'L'} ${x(i)} ${y(d[key])}`).join(' ');
    }
    // area wash under allowed (subtle)
    const areaPath = pathFor('allowed') + ` L ${x(n - 1)} ${padT + plotH} L ${x(0)} ${padT + plotH} Z`;
    svg.appendChild(el('path', { d: areaPath, fill: cssVar('--series-allowed'), opacity: 0.08, stroke: 'none' }));

    svg.appendChild(el('path', { d: pathFor('allowed'), fill: 'none', stroke: cssVar('--series-allowed'), 'stroke-width': 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));
    svg.appendChild(el('path', { d: pathFor('blocked'), fill: 'none', stroke: cssVar('--series-blocked'), 'stroke-width': 2, 'stroke-linejoin': 'round', 'stroke-linecap': 'round' }));

    // hover crosshair + hit layer
    const crosshair = el('line', { x1: 0, x2: 0, y1: padT, y2: padT + plotH, class: 'grid-line', style: 'display:none' });
    svg.appendChild(crosshair);
    const dotA = el('circle', { r: 4, fill: cssVar('--series-allowed'), stroke: cssVar('--surface-1'), 'stroke-width': 2, style: 'display:none' });
    const dotB = el('circle', { r: 4, fill: cssVar('--series-blocked'), stroke: cssVar('--surface-1'), 'stroke-width': 2, style: 'display:none' });
    svg.appendChild(dotA); svg.appendChild(dotB);

    const hit = el('rect', { x: padL, y: padT, width: plotW, height: plotH, fill: 'transparent' });
    svg.appendChild(hit);

    hit.addEventListener('mousemove', (ev) => {
      const rect = svg.getBoundingClientRect();
      const mx = (ev.clientX - rect.left) * (W / rect.width);
      let i = Math.round(((mx - padL) / plotW) * (n - 1));
      i = Math.max(0, Math.min(n - 1, i));
      const d = range[i];
      crosshair.setAttribute('x1', x(i)); crosshair.setAttribute('x2', x(i)); crosshair.style.display = '';
      dotA.setAttribute('cx', x(i)); dotA.setAttribute('cy', y(d.allowed)); dotA.style.display = '';
      dotB.setAttribute('cx', x(i)); dotB.setAttribute('cy', y(d.blocked)); dotB.style.display = '';

      tooltip.innerHTML = `
        <div class="t-date">${d.date}</div>
        <div class="t-row"><span class="k"><span class="dot" style="background:${cssVar('--series-allowed')}"></span>Allowed</span><span class="v">${commas(d.allowed)}</span></div>
        <div class="t-row"><span class="k"><span class="dot" style="background:${cssVar('--series-blocked')}"></span>Blocked</span><span class="v">${commas(d.blocked)}</span></div>
      `;
      tooltip.style.display = 'block';
      const svgBox = svg.getBoundingClientRect();
      const px = (x(i) / W) * svgBox.width;
      tooltip.style.left = Math.min(px + 12, svgBox.width - 170) + 'px';
      tooltip.style.top = '4px';
    });
    hit.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
      crosshair.style.display = 'none';
      dotA.style.display = 'none';
      dotB.style.display = 'none';
    });
  })();

  // ---- Horizontal bar chart builder ----
  function buildBarChart(svgId, rows, key, color, labelKey) {
    const svg = document.getElementById(svgId);
    const W = 540, rowH = 28, padL = 200, padR = 54, padT = 6;
    const n = rows.length;
    const H = padT + n * rowH + 6;
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    const plotW = W - padL - padR;
    const maxV = Math.max(...rows.map(r => r[key]));
    const svgns = 'http://www.w3.org/2000/svg';
    function el(tag, attrs) {
      const e = document.createElementNS(svgns, tag);
      for (const k in attrs) e.setAttribute(k, attrs[k]);
      return e;
    }
    rows.forEach((r, i) => {
      const cy = padT + i * rowH;
      const barW = Math.max(2, (r[key] / maxV) * plotW);
      const label = el('text', { x: padL - 10, y: cy + rowH / 2 + 4, 'text-anchor': 'end' });
      label.textContent = r[labelKey].length > 26 ? r[labelKey].slice(0, 25) + '…' : r[labelKey];
      label.setAttribute('fill', cssVar('--text-secondary'));
      svg.appendChild(label);

      svg.appendChild(el('rect', {
        x: padL, y: cy + 4, width: barW, height: rowH - 12,
        rx: 4, ry: 4, fill: color,
      }));
      const val = el('text', { x: padL + barW + 8, y: cy + rowH / 2 + 4 });
      val.textContent = compact(r[key]);
      val.setAttribute('fill', cssVar('--text-primary'));
      val.style.fontWeight = '600';
      svg.appendChild(val);
    });
  }
  buildBarChart('cat-chart', DATA.top_categories.slice(0, 8), 'count', cssVar('--seq-400'), 'label');
  buildBarChart('blocked-cat-chart', DATA.top_blocked_categories.slice(0, 8), 'blocked', cssVar('--series-blocked'), 'label');

  // ---- Tables ----
  function fillTable(tableId, rows, countKey) {
    const tbody = document.querySelector(`#${tableId} tbody`);
    rows.forEach(r => {
      const tr = document.createElement('tr');
      const cats = (r.categories || []).map(c => `<span class="cat-tag">${c}</span>`).join('');
      tr.innerHTML = `<td>${r.domain}</td><td>${cats || '<span class="cat-tag">Uncategorized</span>'}</td><td class="num">${commas(r[countKey])}</td>`;
      tbody.appendChild(tr);
    });
  }
  fillTable('dest-table', DATA.top_destinations, 'count');
  fillTable('blocked-dest-table', DATA.top_destinations_blocked, 'count');

  // ---- Site / network roster ----
  document.getElementById('sites-heading').textContent = `Site / network roster (${DATA.sites.length})`;
  const sitesBody = document.querySelector('#sites-table tbody');
  DATA.sites.forEach(s => {
    const tr = document.createElement('tr');
    const verified = s.verified
      ? '<span class="verified-yes">Verified</span>'
      : '<span class="verified-no">Unverified</span>';
    tr.innerHTML = `<td>${s.name}</td><td class="num">${s.ip_address || '—'}</td><td>${verified}</td><td class="num">${s.created_at}</td><td class="num allowed-ink">${commas(s.allowed)}</td><td class="num blocked-ink">${commas(s.blocked)}</td>`;
    sitesBody.appendChild(tr);
  });

  // ---- Threat note ----
  const evNote = document.getElementById('threat-note');
  if (DATA.event_types.length === 0) {
    evNote.textContent = 'No security event types were recorded in this period.';
  } else {
    const parts = DATA.event_types.map(e => `${e.eventtype.replace('_', ' ')}: ${commas(e.count)} events`).join(', ');
    evNote.innerHTML = `${parts}. No malware, phishing, or C2 domains were flagged by Umbrella's threat-intelligence categories in this window — the ${s.block_rate_pct}% block rate seen above is driven almost entirely by <strong>content/application policy</strong> (software updates, social media, ads, streaming), not active threats.`;
  }

  document.getElementById('footer-note').textContent =
    `Generated ${new Date().toISOString().slice(0, 10)} · Source: Cisco Umbrella Reporting API v2`;
})();
</script>

